  const W = box.clientWidth, narrow = W < 600, rowH = narrow ? 44 : 30;
  const svg = d3.select(box).append('svg').attr('width', '100%');
  const labW = narrow ? 0 : Math.min(W * 0.38, d3.max(rows, (r) => tw(svg, r.obra, 'lbl')) + 14), top = 24, H = rows.length * rowH + top + 6;
